/**
 * Calculate late fee on an invoice: 0.04% of amount due per day overdue.
 * @param {{ status: string, dueDate: string, lines: Array, payments?: Array, voucher?: any }} invoice
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number} - Late fee in cents, or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (!invoice || !['issued', 'partially_paid'].includes(invoice.status)) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  if (daysOverdue <= 0) {
    return 0;
  }

  const due = balanceDue(invoice);
  const fee = roundCents(due * (daysOverdue * 0.04 / 100));

  return Math.max(0, fee);
}

/**
 * Get a dashboard snapshot of invoices as of a given date.
 * @param {Array<{ status: string, customerId: string, dueDate: string, lines: Array, payments?: Array, voucher?: any }>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  let outstanding = 0;
  const customerDueMap = {};

  for (const invoice of invoices) {
    if (!invoice) continue;

    counts[invoice.status] = (counts[invoice.status] || 0) + 1;

    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
      const due = balanceDue(invoice);
      outstanding += due;

      const customerId = invoice.customerId;
      customerDueMap[customerId] = (customerDueMap[customerId] || 0) + due;
    }
  }

  const overdueList = overdueInvoices(invoices, asOf);
  const overdueAmount = overdueList.reduce((sum, inv) => sum + inv.due, 0);

  const topCustomers = Object.entries(customerDueMap)
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue: {
      count: overdueList.length,
      amount: overdueAmount,
    },
    topCustomers,
  };
}

