import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary, lateFee, dashboard } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array for empty invoices list', () => {
  const r = overdueInvoices([], '2026-10-10');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes draft invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const r = overdueInvoices([invoice], '2026-10-15');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 10285, date: '2026-10-08' }).value;

  const r = overdueInvoices([paid], '2026-10-15');
  assert.deepEqual(r, []);
});

test('overdueInvoices excludes invoices not yet due', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2026-10-07 = due 2026-11-06

  const r = overdueInvoices([issued], '2026-11-05');
  assert.deepEqual(r, []);
});

test('overdueInvoices includes invoices with dueDate before asOf', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET14 from 2026-10-07 = due 2026-10-21
  const r = overdueInvoices([issued], '2026-10-22');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].daysOverdue, 1);
});

test('overdueInvoices excludes invoices due on asOf date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET14 from 2026-10-07 = due 2026-10-21
  const r = overdueInvoices([issued], '2026-10-21');

  assert.deepEqual(r, []);
});

test('overdueInvoices includes partially paid overdue invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET14 from 2026-10-01 = due 2026-10-15, C-002 standard tier total 10285
  const partial = recordPayment(issued, { amount: 5000, date: '2026-10-08' }).value;

  const r = overdueInvoices([partial], '2026-10-20');

  assert.equal(r.length, 1);
  assert.equal(r[0].number, 'INV-2026-0001');
  assert.equal(r[0].daysOverdue, 5);
  assert.equal(r[0].due, 5285);
});

test('overdueInvoices returns correct structure', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  // NET30 from 2026-10-01 = due 2026-10-31, checking as of 2026-11-15 (overdue)
  const r = overdueInvoices([issued], '2026-11-15');

  assert.equal(r.length, 1);
  const inv = r[0];
  assert.ok(inv.number);
  assert.ok(inv.customerId);
  assert.ok(inv.dueDate);
  assert.equal(typeof inv.daysOverdue, 'number');
  assert.equal(typeof inv.due, 'number');
  assert.equal(Object.keys(inv).length, 5);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

