  assert.equal(r[0].vat, 3392);
});

test('vatSummary with different VAT rates and discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'PRINT-A4', qty: 50, discountPercent: 5 },
    ],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const r = vatSummary([issued]);

  assert.equal(r.length, 2);
  // DES-HOUR 21%: base = 17000 - 1700 = 15300, vat = 3213
  assert.equal(r[0].rate, 21);
  assert.equal(r[0].base, 15300);
  assert.equal(r[0].vat, 3213);
  // PRINT-A4 9%: base = 1850 - 93 (5% of 1850, rounds to 93) = 1757, vat = 158 (rounding 158.13)
  assert.equal(r[1].rate, 9);
  assert.equal(r[1].base, 1757);
  assert.equal(r[1].vat, 158);
});

